def solve(pairs):
    if not pairs:
        return pairs

    result = {}
    order = []

    for name, score in pairs:
        if name not in result:
            result[name] = score
            order.append(name)
        else:
            result[name] = max(result[name], score)

    return [f"{name}:{result[name]}" for name in order]
